"""Version ranges, as written in manifests and in index dependencies (docs/ranges.md)."""

import re

from pinset.errors import RangeError, VersionError
from pinset.version import BUILD_RE, PRERELEASE_RE, Version

OPERATORS = ("<=", ">=", "<", ">", "=", "^", "~")
WILD = ("x", "X", "*")
_NUM = re.compile(r"0|[1-9][0-9]*")
_START = "0123456789xX*"

# A comparator is (kind, version, carries): kind in ">=", ">", "<", "<=", "=", "never".
# `carries` is True when the version was written with a prerelease.
_NEVER = ("never", None, False)


class Range:
    def __init__(self, text, alternatives, exact):
        self.text = text
        self._alts = alternatives  # list of lists of comparators
        self._exact = exact

    @staticmethod
    def _holds(comp, v):
        kind, b, _ = comp
        if kind == "never":
            return False
        if kind == ">=":
            return v >= b
        if kind == ">":
            return v > b
        if kind == "<":
            return v < b
        if kind == "<=":
            return v <= b
        return v == b

    def test(self, version: Version) -> bool:
        """True when `version` satisfies the range."""
        for alt in self._alts:
            if not all(self._holds(c, version) for c in alt):
                continue
            if version.is_prerelease() and not any(
                c[2] and c[1].release == version.release for c in alt
            ):
                continue
            return True
        return False

    def is_exact(self) -> bool:
        """True for a range that names one version (docs/resolve.md, section 4)."""
        return self._exact

    def __str__(self):
        return self.text


def _bad_version(msg):
    return RangeError("bad-version", msg)


def _parse_partial(text):
    """Returns (numbers, version_or_None): numbers is the list of leading numeric parts."""
    cut = len(text)
    for i, ch in enumerate(text):
        if ch in "-+":
            cut = i
            break
    core, rest = text[:cut], text[cut:]
    parts = core.split(".")
    if len(parts) > 3:
        raise _bad_version(f"too many parts in {text!r}")
    nums = []
    wild = False
    for part in parts:
        if part in WILD:
            wild = True
        elif _NUM.fullmatch(part):
            if wild:
                raise _bad_version(f"number after wildcard in {text!r}")
            nums.append(int(part))
        else:
            raise _bad_version(f"bad part {part!r} in {text!r}")
    if rest:
        if len(nums) != 3:
            raise _bad_version(f"prerelease or build on a partial version {text!r}")
        pre = build = ""
        m = re.fullmatch(r"(?:-([^+]*))?(?:\+(.*))?", rest, re.S)
        if m is None:
            raise _bad_version(f"bad version {text!r}")
        pre, build = m.group(1), m.group(2)
        if pre is not None and not PRERELEASE_RE.fullmatch(pre):
            raise _bad_version(f"bad prerelease in {text!r}")
        if build is not None and not BUILD_RE.fullmatch(build):
            raise _bad_version(f"bad build in {text!r}")
    version = None
    if len(nums) == 3:
        try:
            version = Version.parse(text)
        except VersionError as e:
            raise _bad_version(str(e)) from None
    return nums, version


def _fill(nums):
    return Version(*(nums + [0] * (3 - len(nums))))


def _lowest(nums):
    """`<X-0` where X is the release just past the block `nums` (1 or 2 numbers)."""
    return _next_block(nums, "<")


def _next_block(nums, kind):
    if len(nums) == 1:
        nxt = Version(nums[0] + 1, 0, 0, ("0",) if kind == "<" else ())
    else:
        nxt = Version(nums[0], nums[1] + 1, 0, ("0",) if kind == "<" else ())
    return (kind, nxt, False)


def _below_block(nums):
    return ("<", Version(*(nums + [0] * (3 - len(nums))), ("0",)), False)


def _comparators(op, nums, version):
    n = len(nums)
    if op in ("", "="):
        if n == 0:
            return []
        if n == 3:
            return [("=", version, bool(version.prerelease))]
        return [(">=", _fill(nums), False), _next_block(nums, "<")]
    if op == ">":
        if n == 0:
            return [_NEVER]
        if n == 3:
            return [(">", version, bool(version.prerelease))]
        return [_next_block(nums, ">=")]
    if op == ">=":
        if n == 0:
            return []
        return [(">=", version or _fill(nums), bool(version and version.prerelease))]
    if op == "<":
        if n == 0:
            return [_NEVER]
        if n == 3:
            return [("<", version, bool(version.prerelease))]
        return [_below_block(nums)]
    if op == "<=":
        if n == 0:
            return []
        if n == 3:
            return [("<=", version, bool(version.prerelease))]
        return [_next_block(nums, "<")]
    # caret and tilde
    if n == 0:
        return []
    low = (">=", version or _fill(nums), bool(version and version.prerelease))
    if op == "^" or n == 1:
        up = ("<", Version(nums[0] + 1, 0, 0, ("0",)), False)
    else:
        up = ("<", Version(nums[0], nums[1] + 1, 0, ("0",)), False)
    return [low, up]


def _hyphen(lo, hi):
    out = []
    lnums, lver = lo
    hnums, hver = hi
    if lnums:
        out.append((">=", lver or _fill(lnums), bool(lver and lver.prerelease)))
    if hnums:
        if len(hnums) == 3:
            out.append(("<=", hver, bool(hver.prerelease)))
        else:
            out.append(_next_block(hnums, "<"))
    return out


def _is_op_start(tok):
    return tok.startswith(OPERATORS)


def _split_op(tok):
    for op in OPERATORS:
        if tok.startswith(op):
            return op, tok[len(op):]
    return "", tok


def parse_range(text: str) -> Range:
    if not isinstance(text, str):
        raise RangeError("bad-range", f"a range is a string, not {type(text).__name__}")
    if not text.strip(" \t"):
        raise RangeError("bad-range", "empty range")
    raw_alts = text.split("||")
    for a in raw_alts:
        if not a.strip(" \t"):
            raise RangeError("bad-range", "empty alternative")
    alts = []
    exact = False
    for a in raw_alts:
        tokens = re.split(r"[ \t]+", a.strip(" \t"))
        if "-" in tokens:
            if len(tokens) != 3 or tokens[1] != "-":
                raise RangeError("bad-range", f"misplaced '-' in {a!r}")
            if _is_op_start(tokens[0]) or _is_op_start(tokens[2]):
                raise RangeError("bad-range", f"operator in a hyphen range {a!r}")
            lo = _parse_partial(tokens[0])
            hi = _parse_partial(tokens[2])
            alts.append(_hyphen(lo, hi))
            continue
        split = []
        for tok in tokens:
            op, rest = _split_op(tok)
            if not rest or rest[0] not in _START:
                raise RangeError("bad-range", f"cannot read {tok!r}")
            split.append((op, rest))
        comps = []
        for op, rest in split:
            nums, version = _parse_partial(rest)
            comps.extend(_comparators(op, nums, version))
            if len(split) == 1 and len(raw_alts) == 1 and op in ("", "=") and version is not None:
                exact = True
        alts.append(comps)
    return Range(text, alts, exact)
